(window.webpackJsonp=window.webpackJsonp||[]).push([[75],{515:function(t,s,v){"use strict";v.r(s);var _=v(11),n=Object(_.a)({},(function(){var t=this,s=t.$createElement,v=t._self._c||s;return v("ContentSlotsDistributor",{attrs:{"slot-key":t.$parent.slotKey}},[v("p",[v("font",{attrs:{size:"5"}},[t._v("摘要：")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("1、最深的伤害往往来自亲人，因为我们对亲人总有最多的期盼。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("2、神要的不是你爱他胜于爱你的亲人，而是要你全部的爱；他要的不是入赘你家，而是要你跟着他一起私奔。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("3、先与神来一场私奔——抛弃掉文化带来的世俗人伦关系，然后再回归——重新建立为神而活的人伦关系。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("4、不能照顾好亲人，首先不是去研究如何按照圣经来照顾他们，而是先要撇弃他们，疯狂地与神私奔。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("一、爱有多销魂，就有多伤人")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("如果要把我最多伤害过的人列一个清单，我的妻子、父母和孩子应该是排在最前面的。我的妻子无比地爱我和信任我，但我所做的事情却常常让她感到对家庭的绝望；我的父母无比地爱我和保护我，但我曾经对他们说过你想象不到的恶毒话；而我的孩子，可能是承受我的凶暴最多的人。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("如果要把对我伤害最多的人列一个清单，我的妻子、父母和孩子应该也是排名在最前面的。替我做主、不合我意、对我嘶吼等等，都会让我觉得愤怒和烦躁。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("人们常质疑：“对外人都做不出的事情，怎能对自己的亲人做出？”但据我观察，大部分情况恰恰是对外人做不出的事情，却对亲人能够做出来。就拿我来说吧，我对外人都习惯于客客气气，彬彬有礼；但对最近的亲人，有时就会怒目相向，甚至曾经说出最恶毒的话，做出最令人伤心的事情来。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我相信每个家庭可能情况都类似，只是程度不太一样，有的极端一点，有的没那么极端。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("为什么会这样呢？最简单直接的答案就是因为罪，每一个家庭成员都带着罪性生活在一起，在频繁的交往接触中，罪性彼此激荡，一些激烈的事件就会产生出来，比如吵架甚至打架等等。今年出现的“新冠离婚”，就是这种现象的一个注脚。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("但为什么往往这些事情发生在亲人之间，我们会觉得是更痛？我想，这是因为现实操作而形成的一种人伦观念的文化：人们往往与亲人相处时间最长、投入的精力最多，所期望从亲人那里得到的回报（或者正面的回应）自然也就最多。这久而久之，就形成了“亲人”与“外人”有别、“血浓于水”、“淡漠亲情是不好的”这种种的观念与文化。中国人最熟悉的，当然就是儒家的那套上慈下孝的传统伦理观念。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("这些人伦观念，导致我们对亲人有着对外人不同的期待。我会期待我的父母对我好，但我不会期待隔壁的李奶奶对我好；我会期待我的儿子爱我，但不会期待隔壁的小明也同样爱我。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("当彼此的罪性在生活中激荡，导致我没有从亲人那里得到我所期待的，我就会觉得很受伤害；积累起来，可能就会引起一些激烈的冲突。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("林忆莲在《伤痕》里唱到，“爱有多销魂，就有多伤人”，部分地表达了这个道理。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("二、为爱痴狂")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我遇到过一些为寻求解决和亲人的关系而到教会中来的人。他们真心地祈祷、急切地盼望着上帝用大能的手来改变这些破碎的关系。有时候并不“灵验”，于是就离开了。他们对福音其实并不是太感兴趣。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我也遇到过一些主里的兄弟姐妹，因为和亲人的关系不和而流泪、叹息。家庭不和睦带来的对心灵的伤害，有时候甚至远超出我的预期。他们是信福音的，当然明白“神爱我们“、”神在一切事上掌权“、”我们的好处不在神以外“这些道理。但有时候面对亲人的伤害，还是很难受安慰，由爱生恨、生怨的事情常常发生。有的人有条件逃避，寄希望于时间来抚平伤痛；有的人没有条件逃避，在煎熬中灵性之火一天天被消磨。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("基督徒到底应该如何对待自己的亲人？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("耶稣说，你要撇下亲人来跟随他：")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("“爱父母过于爱我的，不配作我的门徒；爱儿女过于爱我的，不配作我的哦门徒。”（马太福音10：37）")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("“人到我这里来，若不爱我胜过爱自己的父母、妻子、儿女、弟兄、姐妹，和自己的姓名，就不能作我的门徒。”（路加福音14：26）")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("“你们无论什么人，若不撇下一切所有的，就不能作我的门徒。”（路加福音24：33）")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("“彼得说，‘看哪，我们已经撇下自己所有的跟从你了。’耶稣说：‘我实在告诉你们，人为神的国撇下房屋，或是妻子、弟兄、父母、儿女，没有在今世不得百倍，在来世不得永生的。’”（路加福音18：30）")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("当有人拿这些经文质问基督徒：这完全是违背人伦的！基督徒一般都知道要这样回答：“撇下“不是仅仅理解成是抛妻弃子去当传道人，而主要是指你要爱神胜过你的亲人。紧接着，基督徒会拿出一些别的经文，证明基督教并不是反人伦的，比如这些：\n“当孝敬父母。”（出埃及记20：12）")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("“你们各人都当爱妻子，如同爱自己一样。妻子也当敬重他的丈夫。“（以弗所书5：33）")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("仿佛这些经文可以让人放心，信基督不会贬损我们在世上的人伦关系。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("真是这样吗？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("耶稣要求跟随他的人撇下亲人，就像撇下房屋一样。对房屋不能留念，对亲人也不能留念。这是第一步要做的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("“撇下“不光是要爱神胜过爱亲人，而是要根本地撇弃——不以他们为目的，不从他们得满足！简而言之，不为他们而活。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("如果你希望孩子能够考上北大清华，他的成功能让你带来“满足感”或“放心感”，因此你努力来教育他，这叫做为孩子而活。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("如果你希望妻子对你的尊重和爱能够给你带来“舒心感”或“自尊感”，因此你爱她照顾她，这叫为妻子而活。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("如果你希望父母的健康能给你带来“安心感”或“方便感”，因此你努力来照顾好他们的起居，这叫为父母而活。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("如果你希望家庭的和睦能够给你带来“幸福感”或“平静感”，因此你努力地去维护家人的关系，这叫为家人而活。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("你希望从哪里满足你的所需，你就是在为什么而活。或者我们用圣经的话说，“你的财宝在哪里，你的心就在那里“（马太福音6：21）。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("财宝代表着那些满足我们自己所需的事情。我把所需寄托于妻子身上，我的心就在她那里；寄托于父母身上，我的心就在他们那里；寄托于房子上，我的心就在房子的事情上；寄托于工作，我的心就在工作上；寄托于家人和睦，那我的心就在他们身上。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("然而，神要求的是你把财宝放在天上！")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("神要求的是你的心在他那里！")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("神要求的是你单纯地相信，你的好处不在他以外！")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("神要求的是你真的相信，你要鸡蛋，他不会给你蝎子！")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("没有讨价还价，没有模棱两可，没有似是而非，没有扭扭捏捏！")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("他要求跟随他的人要撇下所有的，包括最亲的亲人。就是这么简单粗暴！")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("他要的不是你爱他胜于爱你的亲人，而是要你全部的爱！他要的不是入赘你家，而是要你跟着他一起私奔！")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("神疯狂地爱着你，现在轮到你了。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("正如刘若英所唱，“想要问问你敢不敢，像你说过的那样爱神？想要问问你敢不敢，像神这样为爱痴狂？”")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("三、一切都是新的")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("如果你敢——亲疏有别、血浓于水、父慈子孝、夫唱妇随、相敬如宾等等的人伦观念都抛弃掉，你不顾一切地去爱神，只求从他那里得到满足——然后才是第二步的问题：我要怎么对待我周围的人？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("神喜悦我孝敬父母——为讨神喜悦和见证神的荣耀，那我就孝敬父母。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("神喜悦我教养你的孩子——为讨神喜悦和见证神的荣耀，那我就教养孩童。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("神喜悦我为妻子舍己——那我就为妻子舍己。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("神喜悦我帮助你的弟兄——那我就帮助弟兄。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("神喜悦我照顾你的邻舍——那我就照顾邻舍。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("神喜悦我顺服我的官长——那我就顺服官长。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("神喜悦我……——那我就……")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("不是因为我有需要要从他们那里得满足，所以我这样对待他们；而是因为我爱神，神喜悦我这样对待他们，所以我要这样对待他们。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("从外表上看，我展现出来的人伦观念还是和以前一样；但实际在内核当中，我已经变了。我的心变了，我的期望也变了。当我的亲人因为他的罪性而给不了我尊重、爱护、安全感、成就感等等这些东西时，我就不会受到伤害而去怨恨他们，因为我不在乎，我的喜乐不从他们而来，而是从我的神那里而来。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("康来昌牧师在一次讲道中谈到，一个基督徒的妻子会发现，随着丈夫对上帝的爱越来越深，丈夫也越来越爱她；但另一方面她又会发现，丈夫对她的爱越来越与她本人的表现、外貌、性格无关。——这是因为上帝之爱越来越多地注入到丈夫的灵魂里，这种爱是从神而来，不是从她触发。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("在我们与亲人之间，神要做的不是去修补我们的关系，而是把我们和亲人原来的那种人伦关系彻底打破，然后再重新建立一套新的、为神而活的人伦关系。这个过程要从你为了神而背对亲人开始，更具体的说，是从你不求在他们那里获得满足开始；然后因着你对神的爱，再转过身来重新去面对他们。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("读大学期间，如果谁的电脑出问题了，我们常常给人一个简单粗暴的建议：先把旧系统格式化了，然后重装。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("不要忘记耶稣对我们的呼召：彻底格式化那些世俗文化催生的人伦关系，不要企图在新系统和旧系统之间找到某种平衡：")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("“耶稣又对一个人说‘跟从我来！’那人说：‘主，容我先回去埋葬我的父亲。’耶稣说：‘任凭死人埋葬他们的死人，你只管去传扬神国的道。’又有一人说：‘主，我要跟从你，但容我先去辞别我家里的人。’耶稣说：‘手扶着犁向后看的，不配进神的国。’”（路加福音9：59～62）")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("荣神益人，是指为了荣神而去益人；不是指一边想着荣神的事另一边又想着益人的事。最大的诫命是要尽心、尽性、尽力、尽意爱你的神，“其次也相仿”，要爱人如己。是“其次”、“相仿”，不是“同等”，“一样”。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("四、不要被亲属关系捆绑")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("如果我们没有对神痴狂的爱、没有先撇下我们的亲人与神私奔，没有先去格式化我们的亲属关系，就去研究学习“如何按照圣经孝敬父母“，“按照圣经教养儿女的原则”，“圣经中的夫妻相处之道”等等，不仅是本末倒置，而且常常会落在危险当中。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("“罪就会趁着机会，借着诫命叫诸般的贪心在我里头发动。”（罗马书7：9）。这比较复杂，我来讲讲是什么意思：")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("要承认的是，我们对神的爱总是不够痴狂，因此我们或多或少总是希望从人那里得到我们的所需。尤其是当上帝怜悯我们，不时地借着我们的亲人赐下我们所需之时，我们却倾向于把这些仅仅看为是从人而来的脉脉温情，而赞叹世俗的人伦关系真是美好！从而对我们的亲人产生不当有的期望。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("而如果亲人的病痛引起我们的不安感，或者他们身上的罪性引起我们的不快，我们就又会因从亲人那里得不到所期望的而感到悲伤。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("这种时候，神要求我们忍耐，神也借着这些时候给我们机会，让我们去背对我们的亲人，去清除那些对世俗人伦关系的期许，去练习仅仅把盼望放在他身上，并且因着对他的盼望，而再次去重新面向我们的亲人，去服侍他们。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我恳请你不要错过神在这些时候所赐下的这个祝福。“患难生忍耐，忍耐生老练，老练生盼望，盼望必不至于羞耻！”（罗马书5：3～5）这话是真的！")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("但确实有很多时候，神怜悯我们，知道我们软弱到了一个地步，以致于真的忍耐不了，所以他可能也会赐下机会，让我们可以逃避这试探，换一个容易一点的服侍对象。这时候，如果你心中还残存着世俗的人伦观念，这种观念就会借着神那圣洁的律法来攻击你，引发你的贪心：“你看！神要求你要孝敬父母，你却跑了！你连自己的亲人都没有照顾好，还说什么去爱其他人！” “老吾老，以及人之老；幼吾幼，以及人之幼”，这世俗的人伦观念就引动你的贪心——就是你想要获得按照世俗标准而心安理得的那个欲望。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("如此一来，你就被捆绑了。那么是神的律法捆绑你吗？绝不是。是你心里没有被清理干净的世俗人伦观念，借着神的律法来捆绑你。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("因为我的软弱，我忍受不了伤害，因此我未能去按照神的要求照顾好我的亲人，这是罪吗？是罪！因为我的软弱，我忍受不了伤害，因此我未能按照圣经的要求去对待我隔壁的李奶奶、小明，这是罪吗？同样是罪！并且是同样的罪！——就是违背神的律法的罪。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("然而有我的主，谁能定我的罪呢？神不再定我的罪，世俗的人伦标准更不能定我的罪。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("那我是否应该要为因为逃避而没有照顾好我的亲人痛苦呢？是的！但原因不是我没有照顾好他们这件事情本身，而是因为我对神还不够爱，不够疯狂，神痴狂地爱我，我却不敢像他这样痴狂。这导致我看重亲情、看重从亲人那里而来的满足，一旦从他们那儿得不到，我就痛苦、我就忍耐不了。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以我要做的，不是首先去研究怎么按照圣经做父母、做儿女、做妻子丈夫，而是首先要去把我的亲人撇弃，去疯狂地与神私奔，然后，靠着那加给我力量的神，我再回归到他们那里，去服侍他们。")])],1)])}),[],!1,null,null,null);s.default=n.exports}}]);